const c = $input.first().json;
const msg = String($('Chat').first().json.body.message || '').slice(0, 2000);
const slots = c.slots || [];
const history = (c.history || []).map(h => (h.role === 'user' ? 'VISITOR' : 'ASSISTANT') + ': ' + h.content).join('\n');
const prompt = [
  'You are the website chat assistant of Bayview Dental (Davao City). Answer ONLY using CLINIC INFO below. If the answer is not in CLINIC INFO, say you\'ll get a team member and set action "handoff". If the visitor asks for a human, set action "handoff".',
  'Collect, one question at a time and only if missing: service, patient_type (new or returning), preferred_day. Ask for their first name before booking.',
  'When service, patient_type, preferred_day and name are known, offer up to 3 times from OPEN SLOTS on or after that day. When the visitor picks one, set action "book" and booking.starts_at to that exact slot value.',
  'Keep replies under 60 words, warm, no emoji.',
  'Return ONLY JSON: {"reply": string, "fields": {"name"?:string,"service"?:string,"patient_type"?:"new"|"returning","preferred_day"?:string}, "action": "none"|"book"|"handoff", "booking": {"starts_at": string} | null}',
  'CLINIC INFO: ' + (c.kb || ''),
  'OPEN SLOTS (ISO, Asia/Manila):\n' + (slots.length ? slots.map(s => s.iso + ' ' + s.label).join('\n') : 'none'),
  'KNOWN FIELDS: ' + JSON.stringify(c.lead || {}),
  'CONVERSATION: ' + (history || '(new conversation)'),
  'VISITOR: ' + msg,
].join('\n');
return [{ json: { prompt, slots } }];

const fallback = { reply: 'Sorry, let me get a team member to help.', fields: {}, action: 'handoff', booking: null };
const slots = $('Build prompt').first().json.slots || [];
let r;
try {
  if (typeof $input.first().json.text !== 'string') throw new Error('bridge failed');
  const t = $input.first().json.text.replace(/```(?:json)?/g, '');
  r = JSON.parse(t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1));
  if (typeof r.reply !== 'string' || !r.reply.trim()) throw new Error('no reply');
} catch (e) { r = fallback; }
const fields = {};
for (const k of ['name', 'service', 'patient_type', 'preferred_day']) {
  const v = r.fields && r.fields[k];
  if (typeof v === 'string' && v.trim()) fields[k] = v.trim().slice(0, 100);
}
if (fields.patient_type) fields.patient_type = fields.patient_type.toLowerCase();
let action = ['none', 'book', 'handoff'].includes(r.action) ? r.action : 'none';
let booking = null;
if (action === 'book') {
  const want = Date.parse(r.booking && r.booking.starts_at);
  const hit = slots.find(s => Date.parse(s.iso) === want);
  if (hit) booking = { starts_at: hit.iso }; else action = 'none';
}
return [{ json: { reply: r.reply, fields, action, booking } }];
